package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for CommandLine#getParsedOptionValue(char, T)
 */
public class CommandLine_getParsedOptionValue_CharTest {

    /**
     * Test subclass that overrides the String-based overload so we can verify delegation
     * without depending on other CommandLine internals.
     */
    static class TestCommandLine extends CommandLine {
        String lastOptionName;
        Object lastDefaultValue;

        public TestCommandLine() {
            super(); // protected constructor in CommandLine
        }

        @Override
        public <T> T getParsedOptionValue(final String optionName, final T defaultValue) throws ParseException {
            this.lastOptionName = optionName;
            this.lastDefaultValue = defaultValue;
            return defaultValue;
        }
    }

    @Test
    void testCharDelegatesToStringOverload_IntegerDefault() throws Exception {
        TestCommandLine cmd = new TestCommandLine();
        Integer defaultVal = 7;

        Integer returned = cmd.getParsedOptionValue('z', defaultVal);

        assertEquals(defaultVal, returned, "Returned value should be the provided default");
        assertEquals("z", cmd.lastOptionName, "Character should be converted to String and forwarded");
        assertEquals(defaultVal, cmd.lastDefaultValue, "Default value should be forwarded unchanged");
    }

    @Test
    void testCharDelegatesToStringOverload_NullDefault() throws Exception {
        TestCommandLine cmd = new TestCommandLine();

        String returned = cmd.getParsedOptionValue('A', null);

        assertNull(returned, "Returned value should be null when defaultValue is null");
        assertEquals("A", cmd.lastOptionName, "Character should be converted to String and forwarded");
        assertNull(cmd.lastDefaultValue, "Forwarded default should be null");
    }

    @Test
    void testReflectionInvokeMethod_delegatesCorrectly() throws Exception {
        TestCommandLine cmd = new TestCommandLine();

        // Use reflection to invoke the char overload (demonstrates reflective invocation)
        Method m = CommandLine.class.getMethod("getParsedOptionValue", char.class, Object.class);
        Object returned = m.invoke(cmd, 'x', "def");

        assertEquals("def", returned, "Reflection-invoked method should return the provided default");
        assertEquals("x", cmd.lastOptionName, "Character should be converted to String and forwarded");
        assertEquals("def", cmd.lastDefaultValue, "Default value should be forwarded unchanged");
    }
}

